from decimal import Decimal, ROUND_HALF_UP
from typing import Any


def _value(row: dict, key: str) -> Any:
    """Return a legacy field value, treating missing and None as empty."""
    value = row.get(key, "")
    return "" if value is None else value


def _fixed(value: Any, width: int) -> str:
    """Legacy FIXED: left-align, right-pad with spaces, and truncate."""
    text = str(value)
    return text[:width].ljust(width)


def _zpad(value: Any, width: int) -> str:
    """Legacy ZPAD: round half-up to an integer and left-pad with zeroes."""
    cents = Decimal(str(value)).quantize(Decimal("1"), rounding=ROUND_HALF_UP)
    return str(int(cents)).zfill(width)


